  @i.emit_events("test.tag.1", dummy_event_stream())

  now = Time.parse('2016-04-13 18:33:31 -0700')
  Timecop.freeze( now )

  @i.emit_events("test.tag.2", dummy_event_stream())

  assert_equal 0, @i.write_count
